/**
 * Published NASA CARA reference values and independent scipy dblquad oracle.
 * The CSV rows carry units, frame/epoch, tolerance and original source locations;
 * fixtures/NOTICE.md states tolerance rationales and regeneration commands.
 * No expected value in these fixtures is generated by the production engine.
 */
#include "conjunction/pc_method.h"
#include <algorithm>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <sstream>
#include <stdexcept>
#include <string>
#include <vector>

using namespace conjunction;

namespace {
int passed = 0, failed = 0;

// Sources/epochs contain no quoted commas; fail on malformed numeric columns.
std::vector<std::string> split(const std::string& line) {
    std::stringstream stream(line);
    std::vector<std::string> columns;
    for (std::string word; std::getline(stream, word, ',');) columns.push_back(word);
    return columns;
}

void check(bool condition, const std::string& label) {
    if (condition) ++passed;
    else { ++failed; std::printf("FAIL: %s\n", label.c_str()); }
}

struct Fixture {
    std::string name;
    BPlaneGeometry geometry;
    double expected, relative_tolerance, absolute_tolerance;
    bool repaired;
};

std::vector<Fixture> read_fixture(const char* filename) {
    std::ifstream input(std::string(CONJUNCTION_TEST_FIXTURE_DIR) + "/" + filename);
    if (!input) throw std::runtime_error(std::string("Cannot read ") + filename);
    std::vector<Fixture> rows;
    std::string line;
    std::getline(input, line);
    while (std::getline(input, line)) {
        if (line.empty()) continue;
        const auto columns = split(line);
        if (columns.size() != 13) throw std::runtime_error("Malformed fixture row: " + line);
        Fixture row;
        row.name = columns[0];
        row.geometry.xi = std::stod(columns[1]);
        row.geometry.zeta = std::stod(columns[2]);
        row.geometry.sigma_xx = std::stod(columns[3]);
        row.geometry.sigma_xz = std::stod(columns[4]);
        row.geometry.sigma_zz = std::stod(columns[5]);
        row.geometry.combined_radius = std::stod(columns[6]);
        row.expected = std::stod(columns[7]);
        row.relative_tolerance = std::stod(columns[8]);
        row.absolute_tolerance = std::stod(columns[9]);
        row.repaired = std::stoi(columns[10]) != 0;
        rows.push_back(row);
    }
    return rows;
}

void closed_form_isotropic() {
    // The radial integral of a centered isotropic 2-D normal is
    // 1-exp(-R²/(2 sigma²)); units km/km², static plane, no epoch.
    // 2e-12 relative + 2e-15 absolute covers double arithmetic and quadrature.
    for (double radius_over_sigma : {1e-4, 0.1, 1.0, 5.0, 20.0}) {
        BPlaneGeometry geometry;
        geometry.combined_radius = .01;
        const double sigma = geometry.combined_radius / radius_over_sigma;
        geometry.sigma_xx = geometry.sigma_zz = sigma * sigma;
        const double expected = -std::expm1(-.5 * radius_over_sigma * radius_over_sigma);
        const auto result = Foster2D().compute(geometry);
        check(result.converged && std::abs(result.probability - expected) <=
              2e-12 * expected + 2e-15, "closed-form centered isotropic disk");
    }
}

void compare(const char* title, const char* filename, std::size_t expected_count) {
    auto rows = read_fixture(filename);
    check(rows.size() == expected_count, std::string(title) + " fixture count");
    Foster2D method;
    double maximum_relative = 0;
    std::printf("\n%s\n", title);
    std::printf("%-28s %18s %18s %13s %13s\n", "case", "reference", "Foster integral", "relative err", "tolerance");
    for (const auto& row : rows) {
        const auto result = method.compute(row.geometry);
        const double absolute = std::abs(result.probability - row.expected);
        const double relative = row.expected ? absolute / row.expected : 0;
        maximum_relative = std::max(maximum_relative, relative);
        const double allowed = std::max(row.absolute_tolerance,
                                        row.relative_tolerance * std::abs(row.expected));
        std::printf("%-28s %.12e %.12e %.6e %.6e%s\n", row.name.c_str(),
                    row.expected, result.probability, relative,
                    row.relative_tolerance ? row.relative_tolerance : row.absolute_tolerance,
                    row.expected ? "" : " absolute");
        check(std::isfinite(result.probability) && absolute <= allowed,
              row.name + " published tolerance");
        check(result.converged, row.name + " convergence");
        check(result.method == "FOSTER-2D", row.name + " method identity");
        if (row.repaired) check(result.covariance_remediated, row.name + " covariance repair reported");
        if (row.name.rfind("axis-near-", 0) == 0) {
            // Independent dblquad values exercise roundoff near both eigenvector
            // axes, which formerly amplified nearly-zero covariance terms.
            for (const auto& name : {"ALFANO-2005", "LAAS-2015"}) {
                const auto alternate = create_pc_method(name)->compute(row.geometry);
                const double tolerance = std::string(name) == "LAAS-2015" ? 1e-5 : 1e-4;
                const double error = std::abs(alternate.probability - row.expected) / row.expected;
                check(alternate.converged && error <= tolerance,
                      row.name + " " + name + " principal-axis regression");
                std::printf("  %-24s %-12s relative_error=%.9e\n", row.name.c_str(), name, error);
            }
        }
    }
    std::printf("%s: %zu cases; max_relative_error=%.12e\n", title, rows.size(), maximum_relative);
}
} // namespace

int main() {
    try {
        closed_form_isotropic();
        compare("CARA cases", "cara_pc.csv", 21);
        compare("20-geometry dblquad comparison", "pc_dblquad.csv", 20);
    } catch (const std::exception& error) {
        std::fprintf(stderr, "ERROR: %s\n", error.what());
        return 1;
    }
    std::printf("\nCARA/oracle assertions: %d passed, %d failed\n", passed, failed);
    return failed ? 1 : 0;
}
